import{_ as l,C as p,o as a,c,a2 as s,b as o,w as t,a as i,E as d,a3 as r}from"./chunks/framework.CZqXuAiL.js";const _=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"liteshield-xdp/architecture/overview.md","filePath":"liteshield-xdp/architecture/overview.md","lastUpdated":null}'),h={name:"liteshield-xdp/architecture/overview.md"};function u(m,e,f,g,b,P){const n=p("Mermaid");return a(),c("div",null,[e[3]||(e[3]=s('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><blockquote><p><strong>One XDP program, seven BPF maps, one Go binary.</strong> This page walks through the packet pipeline, the map layout, the rate-limiting machinery, and the fail-open design that keeps LiteShield from ever taking your link down.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#design-philosophy">Design Philosophy</a></li><li><a href="#packet-flow">Packet Flow</a></li><li><a href="#bpf-maps">BPF Maps</a><ul><li><a href="#design-decisions-worth-knowing">Design decisions worth knowing</a></li></ul></li><li><a href="#rate-limiting-pipeline">Rate Limiting Pipeline</a></li><li><a href="#fail-open-design">Fail-Open Design</a></li><li><a href="#userspace-↔-kernel-boundary">Userspace ↔ Kernel Boundary</a></li><li><a href="#file-layout">File Layout</a></li><li><a href="#known-trade-offs">Known Trade-offs</a></li></ul></nav><hr><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><p>LiteShield deliberately skips everything that makes eBPF firewalls hard to audit:</p><ul><li><strong>No tail calls, no <code>freplace</code>, no program chaining</strong> — one <code>SEC(&quot;xdp&quot;)</code> program contains the entire pipeline.</li><li><strong>No GPL-only helpers</strong> — only <code>bpf_map_lookup_elem</code>, <code>bpf_map_update_elem</code>, and <code>bpf_ktime_get_ns</code>, all available long before kernel 5.15. The object carries a <code>Dual MIT/GPL</code> license and passes the kernel&#39;s license check on any supported kernel.</li><li><strong>No agent daemon</strong> — the loading process can exit; the pinned link and maps keep enforcing with zero userspace processes.</li></ul><hr><h2 id="packet-flow" tabindex="-1">Packet Flow <a class="header-anchor" href="#packet-flow" aria-label="Permalink to &quot;Packet Flow&quot;">​</a></h2><p>Every inbound packet on the attached interface runs through this pipeline, in order:</p>',10)),(a(),o(r,null,{default:t(()=>[d(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%5B%22Packet%20arrives%3Cbr%2F%3E(NIC%20driver%20%2F%20generic%20hook)%22%5D%20--%3E%20CFG%7B%22config_map%3Cbr%2F%3Epresent%20%26%20enabled%3F%22%7D%0A%20%20%20%20CFG%20--%3E%7C%22no%20%2F%20missing%22%7C%20PASS1%5B%22XDP_PASS%3Cbr%2F%3E(fail%20open)%22%5D%0A%20%20%20%20CFG%20--%3E%7C%22yes%22%7C%20PARSE%5B%22Parse%20L2%2FL3%2FL4%3Cbr%2F%3EEthernet%20%C2%B7%20VLAN%20%C2%B7%20IPv4%2FIPv6%22%5D%0A%20%20%20%20PARSE%20--%3E%7C%22non-IP%20%2F%20malformed%22%7C%20PASS2%5B%22XDP_PASS%3Cbr%2F%3Enot%20our%20business%22%5D%0A%20%20%20%20PARSE%20--%3E%7C%22valid%22%7C%20FRAG%7B%22Fragment%3F%22%7D%0A%20%20%20%20FRAG%20--%3E%7C%22yes%22%7C%20PASS3%5B%22XDP_PASS%3Cbr%2F%3Eno%20L4%20accounting%22%5D%0A%20%20%20%20FRAG%20--%3E%7C%22no%22%7C%20WL%7B%22whitelist_map%3Cbr%2F%3Elookup%20src%22%7D%0A%20%20%20%20WL%20--%3E%7C%22hit%22%7C%20PASS4%5B%22XDP_PASS%3Cbr%2F%3Ewhitelist_hits%2B%2B%22%5D%0A%20%20%20%20WL%20--%3E%7C%22miss%22%7C%20BL%7B%22blacklist_map%3Cbr%2F%3Elookup%20src%22%7D%0A%20%20%20%20BL%20--%3E%7C%22permanent%20or%20unexpired%22%7C%20DROP1%5B%22XDP_DROP%3Cbr%2F%3Eblacklist_hits%2B%2B%22%5D%0A%20%20%20%20BL%20--%3E%7C%22miss%20%2F%20expired%22%7C%20KNOWN%7B%22ip_stats_map%3Cbr%2F%3Ehas%20entry%3F%22%7D%0A%20%20%20%20KNOWN%20--%3E%7C%22no%22%7C%20NSW%7B%22new_src%20window%3Cbr%2F%3Ecount%20%3E%20limit%3F%22%7D%0A%20%20%20%20NSW%20--%3E%7C%22yes%22%7C%20DROP2%5B%22XDP_DROP%3Cbr%2F%3Enew_src_drops%2B%2B%22%5D%0A%20%20%20%20NSW%20--%3E%7C%22no%22%7C%20CREATE%5B%22Insert%20ip_stats%20entry%22%5D%0A%20%20%20%20KNOWN%20--%3E%7C%22yes%22%7C%20BAN%7B%22banned_until_ns%3Cbr%2F%3Ein%20future%3F%22%7D%0A%20%20%20%20CREATE%20--%3E%20BAN%0A%20%20%20%20BAN%20--%3E%7C%22yes%22%7C%20DROP3%5B%22XDP_DROP%3Cbr%2F%3Eban_drops%2B%2B%22%5D%0A%20%20%20%20BAN%20--%3E%7C%22no%20%2F%20expired%22%7C%20ACCT%5B%221-second%20window%20accounting%3Cbr%2F%3Epps%20%C2%B7%20syn%20%C2%B7%20udp%20%C2%B7%20icmp%22%5D%0A%20%20%20%20ACCT%20--%3E%20TH%7B%22Any%20per-IP%20threshold%3Cbr%2F%3Eexceeded%3F%22%7D%0A%20%20%20%20TH%20--%3E%7C%22yes%22%7C%20RBAN%5B%22rule%20drop%2B%2B%3Cbr%2F%3Estart%20auto-ban%20timer%22%5D%20--%3E%20DROP4%5B%22XDP_DROP%22%5D%0A%20%20%20%20TH%20--%3E%7C%22no%22%7C%20FLOW%7B%22flow_stats_map%3Cbr%2F%3Epps%2Fbps%20exceeded%3F%22%7D%0A%20%20%20%20FLOW%20--%3E%7C%22yes%22%7C%20DROP5%5B%22XDP_DROP%22%5D%0A%20%20%20%20FLOW%20--%3E%7C%22no%20%2F%20map%20full%22%7C%20PASS5%5B%22XDP_PASS%3Cbr%2F%3Epassed%2B%2B%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<p>Key properties of the pipeline:</p><ol><li><strong>Whitelist before blacklist before rate limits</strong> — exempted sources skip all accounting; banned sources drop without touching the rate window.</li><li><strong>Auto-ban check before accounting</strong> — banned sources drop on a single timestamp comparison, no counter updates.</li><li><strong>Flow rules last</strong> — the most expensive checks (5-tuple map operations) only run for traffic that survived everything cheaper.</li></ol><hr><h2 id="bpf-maps" tabindex="-1">BPF Maps <a class="header-anchor" href="#bpf-maps" aria-label="Permalink to &quot;BPF Maps&quot;">​</a></h2><p>All seven maps are pinned under <code>/sys/fs/bpf/liteshield/maps/</code> so the CLI can reach them from any later invocation.</p><table tabindex="0"><thead><tr><th>Map</th><th>Type</th><th>Max entries</th><th>Key → Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config_map</code></td><td><code>ARRAY</code></td><td>1</td><td><code>u32</code> → <code>liteshield_config</code></td><td>Runtime thresholds + ban duration + enabled flag. Hot-reload target</td></tr><tr><td><code>global_stats_map</code></td><td><code>PERCPU_ARRAY</code></td><td>1</td><td><code>u32</code> → <code>global_stats</code></td><td>All counters the TUI/<code>status</code> display (per-CPU, summed on read)</td></tr><tr><td><code>ip_stats_map</code></td><td><code>LRU_PERCPU_HASH</code></td><td>65,536</td><td><code>ip_key</code> → <code>ip_stats_val</code></td><td>Per-source-IP rate windows, totals, and auto-ban deadline</td></tr><tr><td><code>whitelist_map</code></td><td><code>HASH</code></td><td>65,536</td><td><code>ip_key</code> → <code>u64</code></td><td>Manual exemptions (IPv4 + IPv6); value is a set timestamp</td></tr><tr><td><code>blacklist_map</code></td><td><code>HASH</code></td><td>65,536</td><td><code>ip_key</code> → <code>u64</code></td><td>Manual bans; value is ban deadline in monotonic ns, <code>0</code> = permanent</td></tr><tr><td><code>new_src_map</code></td><td><code>PERCPU_ARRAY</code></td><td>1</td><td><code>u32</code> → <code>new_src_window</code></td><td>Global new-source-IPs/sec window</td></tr><tr><td><code>flow_stats_map</code></td><td><code>LRU_PERCPU_HASH</code></td><td>131,072</td><td><code>flow_key</code> → <code>flow_stats_val</code></td><td>Per-flow (src+dst+proto+ports) rate windows</td></tr></tbody></table><h3 id="design-decisions-worth-knowing" tabindex="-1">Design decisions worth knowing <a class="header-anchor" href="#design-decisions-worth-knowing" aria-label="Permalink to &quot;Design decisions worth knowing&quot;">​</a></h3><ul><li><strong>Hash maps, not LPM tries.</strong> Whitelist/blacklist use <code>BPF_MAP_TYPE_HASH</code>. CIDR entries are expanded into single addresses (max <code>/24</code>) at insert time by the CLI — the kernel side only ever does exact-match lookups.</li><li><strong>LRU per-IP tracking.</strong> <code>ip_stats_map</code> and <code>flow_stats_map</code> are <code>LRU_PERCPU_HASH</code>, so under a spoofed-source flood the kernel evicts the least-recently-used entries automatically. The map can&#39;t be &quot;filled&quot; as a denial-of-service vector.</li><li><strong>Monotonic-clock bans.</strong> Timed entries store a <code>CLOCK_MONOTONIC</code> deadline — the same clock <code>bpf_ktime_get_ns()</code> reads. Expiry is exact, immune to wall-clock changes (NTP steps, timezone edits), and survives userspace restarts because it lives in the pinned map.</li><li><strong>Per-CPU counters.</strong> Stats maps are per-CPU variants, so packet-path updates never contend on shared cache lines — userspace sums the per-CPU slots when reading.</li></ul><hr><h2 id="rate-limiting-pipeline" tabindex="-1">Rate Limiting Pipeline <a class="header-anchor" href="#rate-limiting-pipeline" aria-label="Permalink to &quot;Rate Limiting Pipeline&quot;">​</a></h2><p>All rate windows are <strong>fixed 1-second buckets</strong>, reset when <code>now - window_start_ns &gt;= 1s</code>:</p>',11)),(a(),o(r,null,{default:t(()=>[d(n,{id:"mermaid-244",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20NIC%0A%20%20%20%20participant%20XDP%20as%20liteshield_xdp%0A%20%20%20%20participant%20IP%20as%20ip_stats_map%0A%20%20%20%20participant%20NS%20as%20new_src_map%0A%20%20%20%20participant%20FL%20as%20flow_stats_map%0A%0A%20%20%20%20NIC-%3E%3EXDP%3A%20packet%20(src%20203.0.113.7)%0A%20%20%20%20XDP-%3E%3EIP%3A%20lookup%20src%0A%20%20%20%20alt%20first%20packet%20from%20this%20source%0A%20%20%20%20%20%20%20%20XDP-%3E%3ENS%3A%20window%20count%2B%2B%0A%20%20%20%20%20%20%20%20NS--%3E%3EXDP%3A%20under%20limit%0A%20%20%20%20%20%20%20%20XDP-%3E%3EIP%3A%20insert%20entry%20(BPF_NOEXIST)%0A%20%20%20%20end%0A%20%20%20%20XDP-%3E%3EIP%3A%20window%20expired%3F%20reset%20pps%2Fsyn%2Fudp%2Ficmp%0A%20%20%20%20XDP-%3E%3EIP%3A%20pps%2B%2B%2C%20proto%20counter%2B%2B%0A%20%20%20%20alt%20pps%20%3E%20thresholds.pps%0A%20%20%20%20%20%20%20%20XDP-%3E%3EIP%3A%20banned_until_ns%20%3D%20now%20%2B%20ban_duration%0A%20%20%20%20%20%20%20%20XDP--%3E%3ENIC%3A%20XDP_DROP%20(pps_drops%2B%2B)%0A%20%20%20%20else%20within%20limits%0A%20%20%20%20%20%20%20%20XDP-%3E%3EFL%3A%20flow%20window%20pps%2B%2B%2Fbps%2B%3Dlen%0A%20%20%20%20%20%20%20%20FL--%3E%3EXDP%3A%20within%20flow%20limits%0A%20%20%20%20%20%20%20%20XDP--%3E%3ENIC%3A%20XDP_PASS%20(passed%2B%2B)%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p>Enforcement order and cost:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Cost</th><th>Catches</th></tr></thead><tbody><tr><td>Whitelist / blacklist</td><td>1 hash lookup</td><td>Known-good / known-bad sources</td></tr><tr><td>New-source window</td><td>1 array increment</td><td>Spoofed-source floods, map exhaustion attempts</td></tr><tr><td>Auto-ban check</td><td>1 integer compare</td><td>Repeat offenders (cheapest possible drop)</td></tr><tr><td>Per-IP thresholds</td><td>4 counter compares</td><td>SYN/UDP/ICMP floods, single-talker PPS floods</td></tr><tr><td>Per-flow thresholds</td><td>1 hash lookup + 2 compares</td><td>Single-connection floods under the per-IP ceiling</td></tr></tbody></table><hr><h2 id="fail-open-design" tabindex="-1">Fail-Open Design <a class="header-anchor" href="#fail-open-design" aria-label="Permalink to &quot;Fail-Open Design&quot;">​</a></h2><p>Every failure path in the program returns <code>XDP_PASS</code>:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>config_map</code> or <code>global_stats_map</code> missing</td><td>Pass — firewall can&#39;t be in an unknown state</td></tr><tr><td><code>enabled</code> flag unset</td><td>Pass — explicit kill switch</td></tr><tr><td>Malformed / non-IP packet</td><td>Pass — not LiteShield&#39;s business</td></tr><tr><td><code>ip_stats_map</code> insert fails (full / lost LRU race)</td><td>Pass — never drop legitimate traffic over bookkeeping</td></tr><tr><td><code>flow_stats_map</code> insert fails</td><td>Pass — same reasoning</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">The trade-off</p><p>Fail-open means a sufficiently exotic kernel-level failure silently disables enforcement rather than the link. Monitor with <code>liteshield status</code> (exit code <code>1</code> when unloaded) from your monitoring stack so a detached program pages a human instead of going unnoticed.</p></div><p>The rationale: LiteShield protects availability. A firewall that fails closed <strong>is</strong> the outage during its own failure modes — an attacker (or a bug) that can break the firewall wins either way.</p><hr><h2 id="userspace-↔-kernel-boundary" tabindex="-1">Userspace ↔ Kernel Boundary <a class="header-anchor" href="#userspace-↔-kernel-boundary" aria-label="Permalink to &quot;Userspace ↔ Kernel Boundary&quot;">​</a></h2>',10)),(a(),o(r,null,{default:t(()=>[d(n,{id:"mermaid-393",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Kernel%0A%20%20%20%20%20%20%20%20PROG%5B%22liteshield_xdp%3Cbr%2F%3ESEC(xdp)%22%5D%0A%20%20%20%20%20%20%20%20MAPS%5B%227%20pinned%20maps%3Cbr%2F%3E%2Fsys%2Ffs%2Fbpf%2Fliteshield%2Fmaps%2F%22%5D%0A%20%20%20%20%20%20%20%20LINK%5B%22pinned%20link%3Cbr%2F%3E%2Fsys%2Ffs%2Fbpf%2Fliteshield%2Flink%22%5D%0A%20%20%20%20%20%20%20%20PROG%20%3C--%3E%20MAPS%0A%20%20%20%20%20%20%20%20LINK%20--%3E%20PROG%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Userspace%5B%22Userspace%20(Go%20binary)%22%5D%0A%20%20%20%20%20%20%20%20LOAD%5B%22load%20%2F%20unload%22%5D%20--%3E%20LINK%0A%20%20%20%20%20%20%20%20STATUS%5B%22status%22%5D%20--%3E%20MAPS%0A%20%20%20%20%20%20%20%20WLCLI%5B%22whitelist%20%2F%20blacklist%22%5D%20--%3E%20MAPS%0A%20%20%20%20%20%20%20%20CONF%5B%22config%20(hot-reload)%22%5D%20--%3E%7C%22config_map%20only%22%7C%20MAPS%0A%20%20%20%20%20%20%20%20TUI2%5B%22TUI%20(1s%20poll)%22%5D%20--%3E%20MAPS%0A%20%20%20%20%20%20%20%20TUI2%20--%3E%20ALRT%5B%22Discord%20alerter%22%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s(`<ul><li><strong>Persistence without a daemon:</strong> the link and maps are pinned to bpffs, so enforcement continues after every userspace process exits. <code>IsLoaded()</code> is just a stat of the pinned link.</li><li><strong>All management is map I/O:</strong> <code>whitelist add</code>, <code>blacklist add</code>, and config hot-reload open the pinned maps and update entries — the running program picks changes up on the very next packet, no re-attach.</li><li><strong>bpffs is auto-mounted</strong> by the loader if your init system didn&#39;t mount it.</li></ul><hr><h2 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiteShield-XDP/</span></span>
<span class="line"><span>├── ebpf/</span></span>
<span class="line"><span>│   ├── liteshield.bpf.c        # the single XDP program (SEC(&quot;xdp&quot;))</span></span>
<span class="line"><span>│   ├── headers/</span></span>
<span class="line"><span>│   │   ├── common.h            # shared constants</span></span>
<span class="line"><span>│   │   ├── config.h            # liteshield_config struct</span></span>
<span class="line"><span>│   │   ├── stats.h             # counter structs</span></span>
<span class="line"><span>│   │   ├── maps.h              # all 7 map definitions</span></span>
<span class="line"><span>│   │   ├── packet.h            # L2/L3/L4 parser</span></span>
<span class="line"><span>│   │   └── vmlinux.h           # generated CO-RE types</span></span>
<span class="line"><span>│   └── Makefile                # clang → liteshield.bpf.o</span></span>
<span class="line"><span>├── userspace/</span></span>
<span class="line"><span>│   └── internal/</span></span>
<span class="line"><span>│       ├── bpf/                # loader, pin management, map CRUD, hot-reload</span></span>
<span class="line"><span>│       ├── cli/                # subcommand dispatch (load/unload/status/…)</span></span>
<span class="line"><span>│       ├── config/             # YAML load/validate, presets, multipliers</span></span>
<span class="line"><span>│       └── tui/                # ANSI status screen + Discord alerter</span></span>
<span class="line"><span>├── configs/</span></span>
<span class="line"><span>│   └── liteshield.example.yaml # annotated example config</span></span>
<span class="line"><span>├── systemd/</span></span>
<span class="line"><span>│   └── liteshield-loader.service  # oneshot loader (load --no-tui)</span></span>
<span class="line"><span>├── install.sh                  # interactive installer</span></span>
<span class="line"><span>├── uninstall.sh                # uninstaller (--purge removes config)</span></span>
<span class="line"><span>└── Makefile                    # make all / make verify</span></span></code></pre></div><p>Installed layout:</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>/opt/liteshield/</code></td><td><code>liteshield</code> binary + <code>liteshield.bpf.o</code></td></tr><tr><td><code>/usr/local/bin/liteshield</code></td><td>Symlink to the binary</td></tr><tr><td><code>/etc/liteshield/liteshield.yaml</code></td><td>Live config (mode <code>0600</code>)</td></tr><tr><td><code>/etc/systemd/system/liteshield-loader.service</code></td><td>Boot-time attach</td></tr><tr><td><code>/sys/fs/bpf/liteshield/</code></td><td>Pinned link + maps (runtime only)</td></tr></tbody></table><hr><h2 id="known-trade-offs" tabindex="-1">Known Trade-offs <a class="header-anchor" href="#known-trade-offs" aria-label="Permalink to &quot;Known Trade-offs&quot;">​</a></h2><ul><li><strong>Fragments pass without L4 accounting.</strong> A fragmented packet carries no usable L4 header in the non-first fragments; LiteShield passes them and rate-limits via the first fragment. A documented trade-off for a minimal parser — pure fragment floods are out of scope (that&#39;s OpenShield territory).</li><li><strong>Fixed 1-second windows.</strong> Bursts straddling a window boundary can briefly exceed the nominal per-second rate. This is standard token-bucket behavior and keeps the hot path branch-free.</li><li><strong>Per-CPU LRU means approximate global state.</strong> Under extreme multi-core load, per-CPU maps make counts approximate. For a rate limiter this is the right trade — exactness is sacrificed for zero contention.</li></ul>`,9))])}const C=l(h,[["render",u]]);export{_ as __pageData,C as default};
